package pp.ua.avertooserver.user.dto;

import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.Size;

/**
 * Request used to create a new Avertoo user.
 *
 * <p>The CAPTCHA token is generated by the client and must be
 * verified by the server before the user is created.</p>
 */
public record CreateUserRequest(

        @NotBlank(message = "Password must not be blank")
        @Size(
                min = 8,
                max = 128,
                message = "Password must be between 8 and 128 characters"
        )
        String password,

        @NotBlank(message = "CAPTCHA token must not be blank")
        String captchaToken
) {
}